1	export type Cell = [x: number, y: number];
2	
3	const isNeighbor = ([x1, y1]: Cell, [x2, y2]: Cell): boolean =>
4	  Math.abs(x1 - x2) <= 1 && Math.abs(y1 - y2) <= 1 && !(x1 === x2 && y1 === y2);
5	
6	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
7	  liveCells.filter((otherCell) => isNeighbor(cell, otherCell)).length;
8	
9	export const nextGeneration = (liveCells: Cell[]): Cell[] =>
10	  liveCells.filter((cell) => {
11	    const liveNeighbors = countLiveNeighbors(cell, liveCells);
12	    return liveNeighbors === 2 || liveNeighbors === 3;
13	  });
